-- FixFlow reference data: site_rules taxonomy + shop catalog.
-- Repeatable: INSERT IGNORE / unique keys; does not overwrite stock or weights.

-- site_rules: SiteType x categories (from SiteRulesSeeder)

-- shop_products: from ShopCatalogSeeder (fixed ids)

-- Existing demo databases were seeded while six products had no photo, so the
-- shop tiles fell back to the placeholder. Fill the missing images, and replace
-- URLs from wikimedia.org / staticflickr.com, which are not reachable from
-- every network; admin-set Pexels URLs are never overwritten.
UPDATE shop_products SET image_url = 'https://images.pexels.com/photos/30413496/pexels-photo-30413496.jpeg?auto=compress&cs=tinysrgb&w=800' WHERE id = 'adjustable-wrench' AND (image_url IS NULL OR image_url = '' OR image_url LIKE '%wikimedia.org%' OR image_url LIKE '%staticflickr.com%');
